source('/home/jinshengxi/bladder_metabolism/results/llps_C5_cellchat_visualization_v3/scripts/common.R');STAGE<-'05_expression_figures.R';startstage();source(file.path(skill,'plot_types/Violin_distribution/plot.R'))
es<-r('tables/expression_summary.csv');db<-r('00_input_audit/DB_components.csv');rg<-unique(unlist(strsplit(db[ligand%in%FOCUS,receptor_genes],';',fixed=TRUE)));rg<-intersect(rg,es$gene)
dot<-function(d,name,genes,groups,balanced=FALSE,role='Main figure candidates'){
 z<-copy(d[gene%in%genes&group%in%groups]);z[,`:=`(value=if(balanced)patient_mean else cell_mean,fraction=if(balanced)patient_fraction else cell_fraction)];p<-ggplot(z,aes(factor(group,levels=groups),factor(gene,levels=rev(genes)),color=value,size=fraction))+geom_point()+scale_size_area(limits=c(0,1),max_size=6,labels=scales::label_percent(),name=if(balanced)'Mean patient detection'else'Cell detection')+scale_color_viridis_c(guide=cb(),name=if(balanced)'Mean patient expression'else'Mean cell expression')+scale_x_discrete(labels=nice)+jin_theme()+labs(x=NULL,y=NULL)+theme(axis.text.x=element_text(angle=35,hjust=1));expfig(p,'06_expression_validation',name,z,10,max(5,length(genes)*.25+2),role=role,source='v2 verified normalized RNA specimen caches',threshold='Expression: >=1 cell per patient-group',unit=if(balanced)'equally weighted patient-condition'else'cell (descriptive)',purpose='Unscaled log-normalized expression and detection',limitation='Expression eligibility differs from CellChat; no cell-level significance test; patient n varies by group')
}
for(bal in c(FALSE,TRUE)){tag<-if(bal)'patient_balanced'else'cell_level';dot(es,paste0('ligand_dotplot_',tag),FOCUS,FIB,bal)
 for(j in seq_len(ceiling(length(rg)/35))){gg<-rg[seq.int((j-1)*35+1,min(j*35,length(rg)))];dot(es,paste0('receptor_dotplot_',tag,'_page',j),gg,c(C5,TME),bal,'Supplementary figures')}
}
v<-r('tables/violin_cells.csv.gz');for(g in unique(v$gene)){d<-v[gene==g];p<-plot_violin_distribution(d,'group','expression',g,order=FIB,colors=cols,ylab=paste(g,'log-normalized expression'))+scale_x_discrete(labels=nice);expfig(p,'06_expression_validation',paste0('ligand_',g,'_violin'),d,8,5,source='v2 verified normalized RNA caches',threshold='All tumor fibro cells',unit='cell (descriptive)',purpose='Formal plotting-skill violin template',limitation='Cell counts differ across patients and subgroups; no independent-cell inference')}
cp<-r('tables/expression_common_patient_pairs.csv');for(g in c('POSTN','FN1','HSPG2','SEMA3C','MDK','ADM')){d<-cp[gene==g&other=='Fibro_C0'];d<-melt(d,id.vars=c('patient_id','dataset','clinical_group','gene'),measure.vars=c('other_mean','C5'),variable.name='group',value.name='value');d[,group:=factor(group,levels=c('other_mean','C5'),labels=c('C0','C5'))];p<-ggplot(d,aes(group,value,group=patient_id,color=dataset))+geom_line(linewidth=.4)+geom_point(size=2)+jin_theme()+labs(x=NULL,y=paste(g,'patient mean expression'),color='Dataset');expfig(p,'06_expression_validation',paste0('ligand_',g,'_C5_C0_common_patients'),d,7,5,role='Supplementary figures',source='v2 verified RNA caches',threshold='>=5 cells in both subgroups in same specimen',purpose='Patient-balanced common-specimen expression',limitation='Exploratory paired means, not pseudobulk DE; no new hypothesis test')}
# All-subgroup specificity as a descriptive common-patient contrast.
d<-r('tables/expression_common_summary.csv');p<-heat(d,'other','gene','median_difference',setdiff(FIB,C5),FOCUS,fillname='C5 - subgroup mean expression')+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',na.value='grey80',guide=cb(),name='Paired median difference')+scale_x_discrete(labels=nice);expfig(p,'06_expression_validation','C5_common_patient_expression_specificity',d,10,8,role='Supplementary figures',source='v2 RNA caches',threshold='>=5 cells per paired subgroup',purpose='Matched expression contrasts',limitation='Independent patient coverage differs; no new DE inference')
